import Database from 'better-sqlite3';
import { and, eq, gte, sql } from 'drizzle-orm';
import { drizzle } from 'drizzle-orm/better-sqlite3';
import { migrate } from 'drizzle-orm/better-sqlite3/migrator';
import { fileURLToPath } from 'node:url';
import { releaseInput, reserveInput } from './contracts.js';
import { items, reservations } from './schema.js';

export type Failure = 'invalid_input' | 'unknown_item' | 'unknown_reservation' | 'duplicate_reservation' | 'insufficient_stock';
export type Result = { ok: true } | { ok: false; error: Failure };

export function openInventory(filename = ':memory:') {
  const sqlite = new Database(filename);
  sqlite.pragma('foreign_keys = ON');
  const db = drizzle(sqlite);
  migrate(db, { migrationsFolder: fileURLToPath(new URL('../drizzle', import.meta.url)) });

  function reserve(input: unknown): Result {
    const parsed = reserveInput.safeParse(input);
    if (!parsed.success) return { ok: false, error: 'invalid_input' };
    const { reservationId, itemId, quantity } = parsed.data;
    return db.transaction((tx): Result => {
      if (tx.select().from(reservations).where(eq(reservations.id, reservationId)).get())
        return { ok: false, error: 'duplicate_reservation' };
      if (!tx.select().from(items).where(eq(items.id, itemId)).get())
        return { ok: false, error: 'unknown_item' };
      const updated = tx.update(items).set({ available: sql`${items.available} - ${quantity}` })
        .where(and(eq(items.id, itemId), gte(items.available, quantity))).run();
      if (!updated.changes) return { ok: false, error: 'insufficient_stock' };
      tx.insert(reservations).values({ id: reservationId, itemId, quantity, status: 'active' }).run();
      return { ok: true };
    }, { behavior: 'immediate' });
  }

  function release(input: unknown): Result {
    const parsed = releaseInput.safeParse(input);
    if (!parsed.success) return { ok: false, error: 'invalid_input' };
    return db.transaction((tx): Result => {
      const reservation = tx.select().from(reservations)
        .where(eq(reservations.id, parsed.data.reservationId)).get();
      if (!reservation) return { ok: false, error: 'unknown_reservation' };
      if (reservation.status === 'released') return { ok: true };
      tx.update(reservations).set({ status: 'released' })
        .where(and(eq(reservations.id, reservation.id), eq(reservations.status, 'active'))).run();
      tx.update(items).set({ available: sql`${items.available} + ${reservation.quantity}` })
        .where(eq(items.id, reservation.itemId)).run();
      return { ok: true };
    }, { behavior: 'immediate' });
  }

  return { sqlite, db, reserve, release, close: () => sqlite.close() };
}

import assert from 'node:assert/strict';
import { After, Before, Given, When, Then, World, setWorldConstructor } from '@cucumber/cucumber';
import { openInventory, type Result } from '../../src/inventory.js';
import { items, reservations } from '../../src/schema.js';

class InventoryWorld extends World {
  inventory!: ReturnType<typeof openInventory>;
  result!: Result;
}
setWorldConstructor(InventoryWorld);
Before(function (this: InventoryWorld) { this.inventory = openInventory(); });
After(function (this: InventoryWorld) { this.inventory.close(); });
Given('item {string} has {int} available units', function (this: InventoryWorld, id: string, available: number) {
  this.inventory.db.insert(items).values({ id, available }).run();
});
When('I reserve {float} units of {string} with ID {string}', function (this: InventoryWorld, quantity: number, itemId: string, reservationId: string) {
  this.result = this.inventory.reserve({ reservationId, itemId, quantity });
});
When('I release reservation {string}', function (this: InventoryWorld, reservationId: string) {
  this.result = this.inventory.release({ reservationId });
});
Then('the operation succeeds', function (this: InventoryWorld) { assert.deepEqual(this.result, { ok: true }); });
Then('the error is {string}', function (this: InventoryWorld, error: string) { assert.deepEqual(this.result, { ok: false, error }); });
Then('{int} units remain available', function (this: InventoryWorld, available: number) {
  assert.equal(this.inventory.db.select().from(items).get()?.available, available);
});
Then('{int} reservations exist', function (this: InventoryWorld, count: number) {
  assert.equal(this.inventory.db.select().from(reservations).all().length, count);
});

import { sql } from 'drizzle-orm';
import { check, integer, sqliteTable, text } from 'drizzle-orm/sqlite-core';

export const items = sqliteTable('items', {
  id: text('id').primaryKey(),
  available: integer('available').notNull(),
}, (table) => [
  check('item_id', sql`length(trim(${table.id})) > 0`),
  check('available_integer', sql`typeof(${table.available}) = 'integer' AND ${table.available} BETWEEN 0 AND 9007199254740991`),
]);

export const reservations = sqliteTable('reservations', {
  id: text('id').primaryKey(),
  itemId: text('item_id').notNull().references(() => items.id),
  quantity: integer('quantity').notNull(),
  status: text('status', { enum: ['active', 'released'] }).notNull(),
}, (table) => [
  check('reservation_id', sql`length(trim(${table.id})) > 0`),
  check('quantity_integer', sql`typeof(${table.quantity}) = 'integer' AND ${table.quantity} BETWEEN 1 AND 9007199254740991`),
  check('reservation_status', sql`${table.status} IN ('active', 'released')`),
]);

import { createInsertSchema } from 'drizzle-zod';
import { z } from 'zod';
import { reservations } from './schema.js';

const identifier = z.string().trim().min(1);
const reservationInput = createInsertSchema(reservations, {
  id: identifier, itemId: identifier, quantity: z.number().int().positive().max(Number.MAX_SAFE_INTEGER),
});
export const reserveInput = reservationInput.pick({ itemId: true, quantity: true })
  .extend({ reservationId: reservationInput.shape.id }).strict();
export const releaseInput = reserveInput.pick({ reservationId: true }).strict();

